
create or replace function public.configure_financial_budget(p_key text,p_payload jsonb) returns uuid language plpgsql security definer set search_path='pg_catalog','public','private','extensions' as $$
declare org uuid;act text;rid uuid;plan uuid;entity uuid;center uuid;begin if auth.uid() is null then raise exception 'UNAUTHORIZED';end if;org:=(p_payload->>'organization_id')::uuid;act:=upper(p_payload->>'action');entity:=nullif(p_payload->>'entity_id','')::uuid;center:=nullif(p_payload->>'cost_center_id','')::uuid;if not public.financial_budget_can(org,entity,center,true) then raise exception 'BUDGET_CONFIG_DENIED';end if;
if act='MAP' then insert into public.financial_budget_mappings(organization_id,plan_id,budget_line_id,classification_id,entity_id,cost_center_id,metric_policy,effective_from,effective_to,created_by) values(org,(p_payload->>'plan_id')::uuid,(p_payload->>'budget_line_id')::uuid,(p_payload->>'classification_id')::uuid,entity,center,p_payload->>'metric_policy',(p_payload->>'effective_from')::date,(p_payload->>'effective_to')::date,auth.uid()) returning id into rid;
elsif act='RETIRE_MAPPING' then insert into public.financial_budget_retirements(organization_id,mapping_id,reason,created_by) values(org,(p_payload->>'mapping_id')::uuid,p_payload->>'reason',auth.uid()) returning id into rid;
elsif act='BIND_PLAN' then plan:=(p_payload->>'plan_id')::uuid;insert into public.financial_budget_plan_ownership(plan_id,organization_id,entity_id,cost_center_id,fiscal_start,adopted_by,legacy_snapshot) select bp.id,org,entity,center,(p_payload->>'fiscal_start')::date,auth.uid(),jsonb_build_object('user_id',bp.user_id,'fiscal_year',bp.fiscal_year,'currency',bp.currency,'scenario',bp.scenario) from public.budget_plans bp where bp.id=plan and bp.user_id=auth.uid() returning plan_id into rid;
else raise exception 'BUDGET_COMMAND_ACTION_INVALID';end if;return rid;end$$;
create or replace function public.financial_budget_consolidated(p_holding uuid,p_year integer,p_scenario text default 'BASE') returns jsonb language plpgsql stable security definer set search_path='pg_catalog','public' as $$declare outj jsonb;begin
with recursive tree as(select id,name from public.organizations where id=p_holding union all select o.id,o.name from public.organizations o join tree t on o.parent_organization_id=t.id),plans as(select bp.id,t.id organization_id,t.name from tree t join public.financial_budget_plan_ownership po on po.organization_id=t.id join public.budget_plans bp on bp.id=po.plan_id where bp.fiscal_year=p_year and bp.scenario=p_scenario)
select coalesce(jsonb_agg(jsonb_build_object('organization_id',organization_id,'organization_name',name,'plan_id',id,'report',public.financial_budget_report(id))),'[]'::jsonb) into outj from plans;
return jsonb_build_object('holding_id',p_holding,'fiscal_year',p_year,'scenario',p_scenario,'organizations',outj);end$$;
grant execute on function public.configure_financial_budget(text,jsonb),public.financial_budget_consolidated(uuid,integer,text) to authenticated;
